% L2
r_a2 = TF_W_2_B*TF_B*TF0_1*trans(dis_of_base_2_shoulder_link2shoulder_link)*[0;0;0;1];
% L3
r_a3 = TF_W_2_B*TF_B*TF0_1*TF1_2*trans(dis_of_shoulder_link2back_arm_link)*[0;0;0;1];
% L4
r_a4 = TF_W_2_B*TF_B*TF0_1*TF1_2*TF2_3*trans(dis_of_back_arm_link2fore_arm_link)*rotm(-180, "z")*[0;0;0;1];
% L5
r_a5 = TF_W_2_B*TF_B*TF0_1*TF1_2*TF2_3*TF3_4*trans(dis_of_fore_arm_link2wrist_link)*rotm(-180, "z")*[0;0;0;1];
% L6
r_a6 = TF_W_2_B*TF_B*TF0_1*TF1_2*TF2_3*TF3_4*TF4_5*trans(dis_of_wrist_link2end_link_r)*[0;0;0;1];
% L7
r_a7 = TF_W_2_B*TF_B*TF0_1*TF1_2*TF2_3*TF3_4*TF4_5*TF5_6*trans(dis_of_arm_2_wrist_link2end_link_r)*rotm(-90, "y")*[0;0;0;1];
r_a = [r_a1, r_a2, r_a3, r_a4, r_a5, r_a6, r_a7];

%% ARM 各杆件质心的位置矢量

% L1
rc_a1 = TF_W_2_B*TF_B*trans(com_of_base_link_r)*[0;0;0;1];
% L2
rc_a2 = TF_W_2_B*TF_B*TF0_1*trans(com_of_base_2_shoulder_link)*[0;0;0;1];
% L3
rc_a3 = TF_W_2_B*TF_B*TF0_1*TF1_2*trans(com_of_shoulder_link)*[0;0;0;1];
% L4
rc_a4 = TF_W_2_B*TF_B*TF0_1*TF1_2*TF2_3*trans(com_of_back_arm_link)*[0;0;0;1];
% L5
rc_a5 = TF_W_2_B*TF_B*TF0_1*TF1_2*TF2_3*TF3_4*trans(com_of_fore_arm_link)*[0;0;0;1];
% L6
rc_a6 = TF_W_2_B*TF_B*TF0_1*TF1_2*TF2_3*TF3_4*TF4_5*trans(com_of_arm_2_wrist_link)*[0;0;0;1];
% L7
rc_a7 = TF_W_2_B*TF_B*TF0_1*TF1_2*TF2_3*TF3_4*TF4_5*TF5_6*trans(com_of_wrist_link)*[0;0;0;1];
% L8
rc_a8 = TF_W_2_B*TF_B*TF0_7*trans(com_of_end_link_r)*[0;0;0;1];


rc = [rc_a1, rc_a2, rc_a3, rc_a4, rc_a5, rc_a6, rc_a7, rc_a8];

%% 各臂末端的位置矢量
% ARM_
Pe = TF_W_2_B*TF_B_E;

%% Modeling of Dual-Arm Space Robots

% ARM_L
% k0_L = TF_W_2_B*TF_B*[0; 0; 1; 0];
k1_L = TF_W_2_B*TF_B*rotm(-180, "z")*trans(dis_of_base_link_r2base_2_shoulder_link)*[0; 0; 1; 0];
k2_L = TF_W_2_B*TF_B*TF0_1*trans(dis_of_base_2_shoulder_link2shoulder_link)*[0; 1; 0; 0];
k3_L = TF_W_2_B*TF_B*TF0_1*TF1_2*trans(dis_of_shoulder_link2back_arm_link)*[0; 0; 1; 0];
k4_L = TF_W_2_B*TF_B*TF0_1*TF1_2*TF2_3*trans(dis_of_back_arm_link2fore_arm_link)*rotm(-180, "z")*[0; 1; 0; 0];
k5_L = TF_W_2_B*TF_B*TF0_1*TF1_2*TF2_3*TF3_4*trans(dis_of_fore_arm_link2wrist_link)*rotm(-180, "z")*[0; 0; 1; 0];
k6_L = TF_W_2_B*TF_B*TF0_1*TF1_2*TF2_3*TF3_4*TF4_5*trans(dis_of_wrist_link2end_link_r)*[0; 1; 0; 0];
k7_L = TF_W_2_B*TF_B*TF0_1*TF1_2*TF2_3*TF3_4*TF4_5*TF5_6*trans(dis_of_arm_2_wrist_link2end_link_r)*rotm(-90, "y")*[0; 0; 1; 0];
k_L = [k1_L, k2_L, k3_L, k4_L, k5_L, k6_L, k7_L];

% J_b_k
J_b = [eye(3) -skew(Pe(1:3)-rb);
         zeros(3)      eye(3)];

% J_m
J_m = [cross(k1_L(1:3), Pe(1:3)-r_a1(1:3)) cross(k2_L(1:3), Pe(1:3)-r_a2(1:3)) cross(k3_L(1:3), Pe(1:3)-r_a3(1:3)) cross(k4_L(1:3), Pe(1:3)-r_a4(1:3)) cross(k5_L(1:3), Pe(1:3)-r_a5(1:3)) cross(k6_L(1:3), Pe(1:3)-r_a6(1:3)) cross(k7_L(1:3), Pe(1:3)-r_a7(1:3));
        k1_L(1:3) k2_L(1:3) k3_L(1:3) k4_L(1:3) k5_L(1:3) k6_L(1:3) k7_L(1:3)];

% J_Ri_k
J_R1_a = [k1_L(1:3) zeros(3,6)];
J_R2_a = [k1_L(1:3) k2_L(1:3) zeros(3,5)];
J_R3_a = [k1_L(1:3) k2_L(1:3) k3_L(1:3) zeros(3,4)];
J_R4_a = [k1_L(1:3) k2_L(1:3) k3_L(1:3) k4_L(1:3) zeros(3,3)];
J_R5_a = [k1_L(1:3) k2_L(1:3) k3_L(1:3) k4_L(1:3) k5_L(1:3) zeros(3,2)];
J_R6_a = [k1_L(1:3) k2_L(1:3) k3_L(1:3) k4_L(1:3) k5_L(1:3) k6_L(1:3) zeros(3,1)];
J_R7_a = [k1_L(1:3) k2_L(1:3) k3_L(1:3) k4_L(1:3) k5_L(1:3) k6_L(1:3) k7_L(1:3)];

%% J_Ti_k
% J_T1_a = [cross(k1_L(1:3), rc_a1(1:3)-r_a1(1:3)) zeros(3,6)];
% J_T2_a = [cross(k1_L(1:3), rc_a2(1:3)-r_a1(1:3)) cross(k2_L(1:3), rc_a2(1:3)-r_a2(1:3)) zeros(3,5)];
% J_T3_a = [cross(k1_L(1:3), rc_a3(1:3)-r_a1(1:3)) cross(k2_L(1:3), rc_a3(1:3)-r_a2(1:3)) cross(k3_L(1:3), rc_a3(1:3)-r_a3(1:3)) zeros(3,4)];
% J_T4_a = [cross(k1_L(1:3), rc_a4(1:3)-r_a1(1:3)) cross(k2_L(1:3), rc_a4(1:3)-r_a2(1:3)) cross(k3_L(1:3), rc_a4(1:3)-r_a3(1:3)) cross(k4_L(1:3), rc_a4(1:3)-r_a4(1:3)) zeros(3,3)];
% J_T5_a = [cross(k1_L(1:3), rc_a5(1:3)-r_a1(1:3)) cross(k2_L(1:3), rc_a5(1:3)-r_a2(1:3)) cross(k3_L(1:3), rc_a5(1:3)-r_a3(1:3)) cross(k4_L(1:3), rc_a5(1:3)-r_a4(1:3)) cross(k5_L(1:3), rc_a5(1:3)-r_a5(1:3)) zeros(3,2)];
% J_T6_a = [cross(k1_L(1:3), rc_a6(1:3)-r_a1(1:3)) cross(k2_L(1:3), rc_a6(1:3)-r_a2(1:3)) cross(k3_L(1:3), rc_a6(1:3)-r_a3(1:3)) cross(k4_L(1:3), rc_a6(1:3)-r_a4(1:3)) cross(k5_L(1:3), rc_a6(1:3)-r_a5(1:3)) cross(k6_L(1:3), rc_a6(1:3)-r_a6(1:3)) zeros(3,1)];
% J_T7_a = [cross(k1_L(1:3), rc_a7(1:3)-r_a1(1:3)) cross(k2_L(1:3), rc_a7(1:3)-r_a2(1:3)) cross(k3_L(1:3), rc_a7(1:3)-r_a3(1:3)) cross(k4_L(1:3), rc_a7(1:3)-r_a4(1:3)) cross(k5_L(1:3), rc_a7(1:3)-r_a5(1:3)) cross(k6_L(1:3), rc_a7(1:3)-r_a6(1:3)) cross(k7_L(1:3), rc_a7(1:3)-r_a7(1:3))];

J_T1_a = [cross(k1_L(1:3), rc_a2(1:3)-r_a1(1:3)) zeros(3,6)];
J_T2_a = [cross(k1_L(1:3), rc_a3(1:3)-r_a1(1:3)) cross(k2_L(1:3), rc_a3(1:3)-r_a2(1:3)) zeros(3,5)];
J_T3_a = [cross(k1_L(1:3), rc_a4(1:3)-r_a1(1:3)) cross(k2_L(1:3), rc_a4(1:3)-r_a2(1:3)) cross(k3_L(1:3), rc_a4(1:3)-r_a3(1:3)) zeros(3,4)];
J_T4_a = [cross(k1_L(1:3), rc_a5(1:3)-r_a1(1:3)) cross(k2_L(1:3), rc_a5(1:3)-r_a2(1:3)) cross(k3_L(1:3), rc_a5(1:3)-r_a3(1:3)) cross(k4_L(1:3), rc_a5(1:3)-r_a4(1:3)) zeros(3,3)];
J_T5_a = [cross(k1_L(1:3), rc_a6(1:3)-r_a1(1:3)) cross(k2_L(1:3), rc_a6(1:3)-r_a2(1:3)) cross(k3_L(1:3), rc_a6(1:3)-r_a3(1:3)) cross(k4_L(1:3), rc_a6(1:3)-r_a4(1:3)) cross(k5_L(1:3), rc_a6(1:3)-r_a5(1:3)) zeros(3,2)];
J_T6_a = [cross(k1_L(1:3), rc_a7(1:3)-r_a1(1:3)) cross(k2_L(1:3), rc_a7(1:3)-r_a2(1:3)) cross(k3_L(1:3), rc_a7(1:3)-r_a3(1:3)) cross(k4_L(1:3), rc_a7(1:3)-r_a4(1:3)) cross(k5_L(1:3), rc_a7(1:3)-r_a5(1:3)) cross(k6_L(1:3), rc_a7(1:3)-r_a6(1:3)) zeros(3,1)];
J_T7_a = [cross(k1_L(1:3), rc_a8(1:3)-r_a1(1:3)) cross(k2_L(1:3), rc_a8(1:3)-r_a2(1:3)) cross(k3_L(1:3), rc_a8(1:3)-r_a3(1:3)) cross(k4_L(1:3), rc_a8(1:3)-r_a4(1:3)) cross(k5_L(1:3), rc_a8(1:3)-r_a5(1:3)) cross(k6_L(1:3), rc_a8(1:3)-r_a6(1:3)) cross(k7_L(1:3), rc_a8(1:3)-r_a7(1:3))];

% J_Tw_k
J_Tw = MassValue(3).*J_T1_a + MassValue(4).*J_T2_a + MassValue(5).*J_T3_a + MassValue(6).*J_T4_a + MassValue(7).*J_T5_a + MassValue(8).*J_T6_a + MassValue(9).*J_T7_a;

% I_W
I_W = I0_I + I1_a_I + MassValue(3).*skew(rc_a2(1:3))*(-skew(rc_a2(1:3)-rb)) + ...
             I2_a_I + MassValue(4).*skew(rc_a3(1:3))*(-skew(rc_a3(1:3)-rb)) + ...
             I3_a_I + MassValue(5).*skew(rc_a4(1:3))*(-skew(rc_a4(1:3)-rb)) + ...
             I4_a_I + MassValue(6).*skew(rc_a5(1:3))*(-skew(rc_a5(1:3)-rb)) + ...
             I5_a_I + MassValue(7).*skew(rc_a6(1:3))*(-skew(rc_a6(1:3)-rb)) + ...
             I6_a_I + MassValue(8).*skew(rc_a7(1:3))*(-skew(rc_a7(1:3)-rb)) + ...
             I7_a_I + MassValue(9).*skew(rc_a8(1:3))*(-skew(rc_a8(1:3)-rb));

% I_Phi_k
I_Phi = I1_a_I*J_R1_a + MassValue(3).*skew(rc_a2(1:3))*J_T1_a + ...
          I2_a_I*J_R2_a + MassValue(4).*skew(rc_a3(1:3))*J_T2_a + ...
          I3_a_I*J_R3_a + MassValue(5).*skew(rc_a4(1:3))*J_T3_a + ...
          I4_a_I*J_R4_a + MassValue(6).*skew(rc_a5(1:3))*J_T4_a + ...
          I5_a_I*J_R5_a + MassValue(7).*skew(rc_a6(1:3))*J_T5_a + ...
          I6_a_I*J_R6_a + MassValue(8).*skew(rc_a7(1:3))*J_T6_a + ...
          I7_a_I*J_R7_a + MassValue(9).*skew(rc_a8(1:3))*J_T7_a;

%% Kinematic Equations of Free-Floating Dual-Arm Space Robot
% 系统质心与基座质心的相对关系
rbg = rg-rb;

% I_s
I_s = M.*skew(rg)*skew(rbg)+I_W;

% I_Theta_k
I_Theta = I_Phi - skew(rg)*J_Tw;

% J_bm_k
J_bm = [-skew(rbg)*inv(I_s)*I_Theta-(J_Tw/M); -inv(I_s)*I_Theta];


%% The end_effector velocity of each manipulator
J = J_b * J_bm + J_m;

%% The GJM of dual-arm space robot
% J = J_b * J_bm + J_m;

% H_m = (J_R1_a')*I1_a_I*J_R1_a + MassValue(3).*(J_T1_a')*J_T1_a + ...
%         (J_R2_a')*I2_a_I*J_R2_a + MassValue(4).*(J_T2_a')*J_T2_a + ...
%         (J_R3_a')*I3_a_I*J_R3_a + MassValue(5).*(J_T3_a')*J_T3_a + ...
%         (J_R4_a')*I4_a_I*J_R4_a + MassValue(6).*(J_T4_a')*J_T4_a + ...
%         (J_R5_a')*I5_a_I*J_R5_a + MassValue(7).*(J_T5_a')*J_T5_a + ...
%         (J_R6_a')*I6_a_I*J_R6_a + MassValue(8).*(J_T6_a')*J_T6_a + ...
%         (J_R7_a')*I7_a_I*J_R7_a + MassValue(9).*(J_T7_a')*J_T7_a;
% 
% H_b = [M.*eye(3), M.*(-skew(rg-rb)); M.*skew(rg) I_W];
% H_bm_a = [J_Tw_a; I_Phi_a];
% H_bm_b = [J_Tw_b; I_Phi_b];
% H_GENERAL = [H_b H_bm_a H_bm_b; H_bm_a' H_m_a zeros(7); H_bm_b' zeros(7) H_m_b];
% M_A_B = [H_m_a, zeros(7); zeros(7), H_m_b] - [H_bm_a'; H_bm_b']*inv(H_b)*[H_bm_a, H_bm_b];
end


