% Items = {'base_of_satellite','continuum_control_base','base_link_c','joint_c','link_c','end_link_c','base_link_r','base_2_shoulder_link','shoulder_link','back_arm_link','fore_arm_link','arm_2_wrist_link','wrist_link','end_link_r'};
% MassValue = [300 16.855 0.0677696914451151 0.00205705301769782 0.0120689559241624 0.0137093667620248 4.456 4.795 4.640 4.511 2.698 1.309 1.240 0.095565];% kg
% mass = containers.Map(Items, MassValue);
function [sys_com_x, sys_com_y, sys_com_z] = com_of_system(rc, base_com)
    MassValue = [500 3.7 3.7 2.7 2.4 2.4 2.4 2.1 1.4];% kg
    Total_mass = sum(MassValue);
    Rb_c = base_com;
    Rg = (500.*Rb_c + ...
    3.7.*rc(:,1) + 3.7.*rc(:,2) + 2.7.*rc(:,3) + ...
    2.4.*rc(:,4) + 2.4.*rc(:,5) + 2.4.*rc(:,6) + 2.1.*rc(:,7) + 1.4.*rc(:,8) )/Total_mass;
    sys_com_x = Rg(1);
    sys_com_y = Rg(2);
    sys_com_z = Rg(3);
end

function TF_W_2_B = TF_W_2_B(RM, TR)


TF_W_2_B = [eye(3) TR;
    0 0 0 1]*[RM [0; 0; 0];
    0 0 0 1];

end
